11	func TestScanReportsForbiddenActiveHits(t *testing.T) {
12		root := t.TempDir()
13		writeFile(t, root, "README.md", "Run ddx-agent with DDX_AGENT_DEBUG=1.\n")
14		writeFile(t, root, "agent.go", "package agent\n")
15		writeFile(t, root, "internal/provider/provider.go", "package provider\n")
16	
17		findings, err := Scan(Options{Root: root})
18		if err != nil {
19			t.Fatalf("Scan() error = %v", err)
20		}
21	
22		assertFinding(t, findings, "README.md", "ddx-agent")
23		assertFinding(t, findings, "README.md", "AGENT_*/DDX_AGENT_*")
24		assertFinding(t, findings, "agent.go", "root package agent")
25		if got := findSurface(findings, "internal/provider/provider.go", "root package agent"); got {
26			t.Fatalf("non-root package was reported as root package agent: %#v", findings)
27		}
28	}
29	
30	func TestScanSkipsAllowlistedHistoricalAndExternalPaths(t *testing.T) {
31		root := t.TempDir()
32		writeFile(t, root, "docs/research/archive.md", "Run ddx-agent from ~/.config/agent.\n")
33		writeFile(t, root, "docs/helix/plan.md", "DDx Agent used .agent state.\n")
34		writeFile(t, root, ".ddx/beads.jsonl", `{"title":"ddx-agent"}`+"\n")
35		writeFile(t, root, ".agents/skills/ddx/SKILL.md", "The .agents directory is external.\n")
36		writeFile(t, root, ".claude/skills/ddx/SKILL.md", "The old ddx-agent skill copy is historical.\n")
37	
38		findings, err := Scan(Options{Root: root})
39		if err != nil {
40			t.Fatalf("Scan() error = %v", err)
41		}
42		if len(findings) != 0 {
43			t.Fatalf("Scan() findings = %#v, want none", findings)
44		}
45	}
46	
47	func TestRunReportOnlyReturnsFindingsAndNoError(t *testing.T) {
48		root := t.TempDir()
49		writeFile(t, root, "config.yaml", "path: .agent/session.jsonl\n")
50		var out bytes.Buffer
51	
52		findings, err := Run(Options{Root: root, Out: &out})
53		if err != nil {
54			t.Fatalf("Run() error = %v", err)
55		}
56		if len(findings) != 1 {
57			t.Fatalf("Run() findings = %d, want 1", len(findings))
58		}
59		if got := out.String(); !strings.Contains(got, "rename-noise: 1 unallowlisted old-name hit") || !strings.Contains(got, "config.yaml:1") {
60			t.Fatalf("Run() output = %q", got)
61		}
62	}
63	
64	func writeFile(t *testing.T, root, rel, content string) {
65		t.Helper()
66		path := filepath.Join(root, filepath.FromSlash(rel))
67		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
68			t.Fatalf("MkdirAll() error = %v", err)
69		}
70		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
71			t.Fatalf("WriteFile() error = %v", err)
72		}
73	}
74	
75	func assertFinding(t *testing.T, findings []Finding, path, surface string) {
76		t.Helper()
77		if !findSurface(findings, path, surface) {
78			t.Fatalf("missing finding for %s %s in %#v", path, surface, findings)
79		}
80	}
81	
82	func findSurface(findings []Finding, path, surface string) bool {
83		for _, f := range findings {
84			if f.Path == path && f.Surface == surface {
85				return true
86			}
87		}
88		return false
89	}
